  1→"use client";
  2→
  3→/**
  4→ * Main chat interface for the thos dashboard.
  5→ *
  6→ * Composes {@link StatusBar}, a scrollable message list ({@link Message}
  7→ * and {@link ControlRequest} cards), and an input bar. The submit button
  8→ * text toggles between "Spawn" (when idle/done) and "Send" (when an
  9→ * agent session is active). Auto-scrolls on new messages.
 10→ *
 11→ * A toggle in the top-right switches between the processed chat view
 12→ * and a raw JSON view of all Claude NDJSON messages.
 13→ *
 14→ * Receives all data and callbacks via props — the parent page component
 15→ * owns the WebSocket hook and orchestrates multiple agents.
 16→ */
 17→
 18→import { useEffect, useMemo, useRef, useState } from "react";
 19→import { ListTodo, MessageSquare, Terminal } from "lucide-react";
 20→import type { AgentStatus, ChatMessage, ClaudeMessage } from "@/lib/types";
 21→import { condenseMessages } from "@/lib/condense-messages";
 22→import { StatusBar } from "./status-bar";
 23→import { AgentSummary } from "./agent-summary";
 24→import { Message } from "./message";
 25→import { ControlRequest } from "./control-request";
 26→import { UserQuestion } from "./user-question";
 27→import { CondensedToolGroup } from "./condensed-tool-group";
 28→import { SlashCommandMenu, filterCommands, type SlashCommand } from "./slash-command-menu";
 29→import { Button } from "@/components/ui/button";
 30→
 31→export function Chat({
 32→  connected,
 33→  loading,
 34→  status,
 35→  agentLabel,
 36→  messages,
 37→  rawMessages,
 38→  activeModel,
 39→  selectedModel,
 40→  onModelChange,
 41→  onSendMessage,
 42→  onSpawnAgent,
 43→  onRespondToControl,
 44→  onRespondToUserQuestion,
 45→  onClearHistory,
 46→  showTasks,
 47→  onToggleTasks,
 48→  showDiffs,
 49→  onToggleDiffs,
 50→  onToggleSidebar,
 51→  onOpenSfxSettings,
 52→}: {
 53→  connected: boolean;
 54→  loading?: boolean;
 55→  status: AgentStatus;
 56→  agentLabel?: string | null;
 57→  messages: ChatMessage[];
 58→  rawMessages: ClaudeMessage[];
 59→  activeModel?: string | null;
 60→  selectedModel?: string;
 61→  onModelChange?: (model: string) => void;
 62→  onSendMessage: (content: string) => void;
 63→  onSpawnAgent: (prompt: string) => void;
 64→  onRespondToControl: (requestId: string, allow: boolean) => void;
 65→  onRespondToUserQuestion: (requestId: string, answers: Record<string, string>) => void;
 66→  onClearHistory?: () => void;
 67→  showTasks?: boolean;
 68→  onToggleTasks?: () => void;
 69→  showDiffs?: boolean;
 70→  onToggleDiffs?: () => void;
 71→  onToggleSidebar?: () => void;
 72→  onOpenSfxSettings?: () => void;
 73→}) {
 74→  const [input, setInput] = useState("");
 75→  const [showRaw, setShowRaw] = useState(false);
 76→  const [showSlashMenu, setShowSlashMenu] = useState(false);
 77→  const [slashQuery, setSlashQuery] = useState("");
 78→  const [slashHighlight, setSlashHighlight] = useState(0);
 79→  const scrollRef = useRef<HTMLDivElement>(null);
 80→  const inputRef = useRef<HTMLInputElement>(null);
 81→
 82→  useEffect(() => {
 83→    scrollRef.current?.scrollTo({
 84→      top: scrollRef.current.scrollHeight,
 85→      behavior: "smooth",
 86→    });
 87→  }, [messages, rawMessages, showRaw]);
 88→
 89→  const displayItems = useMemo(() => condenseMessages(messages), [messages]);
 90→  const isActive = status === "connected" || status === "thinking";
 91→  const isArchived = status === "done" || status === "disconnected" || status === "error";
 92→
 93→  function handleSubmit(e: React.FormEvent) {
 94→    e.preventDefault();
 95→    const trimmed = input.trim();
 96→    if (!trimmed) return;
 97→
 98→    if (isActive) {
 99→      onSendMessage(trimmed);
100→    } else {
101→      onSpawnAgent(trimmed);
102→    }
103→    setInput("");
104→    setShowSlashMenu(false);
105→  }
106→
107→  function handleInputChange(e: React.ChangeEvent<HTMLInputElement>) {
108→    const value = e.target.value;
109→    setInput(value);
110→
111→    if (value.startsWith("/")) {
112→      setShowSlashMenu(true);
113→      setSlashQuery(value.slice(1));
114→      setSlashHighlight(0);
115→    } else {
116→      setShowSlashMenu(false);
117→      setSlashQuery("");
118→    }
119→  }
120→
121→  function handleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
122→    if (!showSlashMenu) return;
123→    const filtered = filterCommands(slashQuery);
124→    if (filtered.length === 0) return;
125→
126→    if (e.key === "ArrowDown") {
127→      e.preventDefault();
128→      setSlashHighlight((i) => (i + 1) % filtered.length);
129→    } else if (e.key === "ArrowUp") {
130→      e.preventDefault();
131→      setSlashHighlight((i) => (i - 1 + filtered.length) % filtered.length);
132→    } else if (e.key === "Enter") {
133→      e.preventDefault();
134→      handleCommandSelect(filtered[slashHighlight]);
135→    } else if (e.key === "Escape") {
136→      e.preventDefault();
137→      setShowSlashMenu(false);
138→    } else if (e.key === "Tab") {
139→      e.preventDefault();
140→      setInput(`/${filtered[slashHighlight].name} `);
141→      setShowSlashMenu(false);
142→    }
143→  }
144→
145→  function handleCommandSelect(command: SlashCommand) {
146→    setShowSlashMenu(false);
147→    setSlashQuery("");
148→    setInput("");
149→
150→    if (command.clientSide) {
151→      if (command.name === "clear") {
152→        onClearHistory?.();
153→      }
154→      return;
155→    }
156→
157→    const commandText = `/${command.name}`;
158→    if (isActive) {
159→      onSendMessage(commandText);
160→    } else {
161→      onSpawnAgent(commandText);
162→    }
163→  }
164→
165→  return (
166→    <div className="flex h-full flex-col">
167→      <StatusBar
168→        connected={connected}
169→        status={status}
170→        agentLabel={agentLabel}
171→        activeModel={activeModel}
172→        selectedModel={selectedModel}
173→        onModelChange={onModelChange}
174→        showRaw={showRaw}
175→        onToggleRaw={() => setShowRaw((v) => !v)}
176→        showTasks={showTasks}
177→        onToggleTasks={onToggleTasks}
178→        showDiffs={showDiffs}
179→        onToggleDiffs={onToggleDiffs}
180→        onToggleSidebar={onToggleSidebar}
181→        onOpenSfxSettings={onOpenSfxSettings}
182→      />
183→
184→      <AgentSummary rawMessages={rawMessages} />
185→
186→      <div ref={scrollRef} className="flex-1 overflow-y-auto p-2 md:p-4 space-y-2">
187→        {loading ? (
188→          <div className="flex h-full flex-col items-center justify-center gap-3">
189→            <div className="flex gap-1">
190→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse" />
191→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:150ms]" />
192→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:300ms]" />
193→            </div>
194→            <span className="text-xs text-muted-foreground">
195→              {connected ? "Loading messages..." : "Connecting..."}
196→            </span>
197→          </div>
198→        ) : showRaw ? (
199→          rawMessages.length === 0 ? (
200→            <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
201→              No raw messages yet
202→            </div>
203→          ) : (
204→            <div className="space-y-1">
205→              {rawMessages.map((msg, i) => (
206→                <RawMessage key={i} message={msg} index={i} />
207→              ))}
208→            </div>
209→          )
210→        ) : (
211→          <>
212→            {messages.length === 0 && (
213→              <div className="flex h-full flex-col items-center justify-center gap-4 text-muted-foreground">
214→                <Terminal className="size-10 opacity-30" />
215→                <div className="text-center">
216→                  <p className="text-sm font-medium text-foreground/80">No agent selected</p>
217→                  <p className="mt-1 text-xs">Type a prompt below to spawn a Claude agent</p>
218→                </div>
219→                <div className="mt-2 grid grid-cols-2 gap-3 text-[11px]">
220→                  <div className="flex items-start gap-2 rounded-lg border p-3">
221→                    <MessageSquare className="mt-0.5 size-3.5 shrink-0 text-primary" />
222→                    <div>
223→                      <p className="font-medium text-foreground/80">Chat</p>
224→                      <p className="mt-0.5">Send prompts and review tool calls in real time</p>
225→                    </div>
226→                  </div>
227→                  <div className="flex items-start gap-2 rounded-lg border p-3">
228→                    <ListTodo className="mt-0.5 size-3.5 shrink-0 text-primary" />
229→                    <div>
230→                      <p className="font-medium text-foreground/80">Tasks</p>
231→                      <p className="mt-0.5">Track work with a kanban board and delegate to agents</p>
232→                    </div>
233→                  </div>
234→                </div>
235→              </div>
236→            )}
237→            {displayItems.map((item) => {
238→              if (item.kind === "condensed") {
239→                return <CondensedToolGroup key={item.id} group={item} onSendMessage={onSendMessage} />;
240→              }
241→              const msg = item.message;
242→              return msg.userQuestion ? (
243→                <UserQuestion
244→                  key={msg.id}
245→                  message={msg}
246→                  onRespond={onRespondToUserQuestion}
247→                />
248→              ) : msg.controlRequest ? (
249→                <ControlRequest
250→                  key={msg.id}
251→                  message={msg}
252→                  onRespond={onRespondToControl}
253→                />
254→              ) : (
255→                <Message key={msg.id} message={msg} onSendMessage={onSendMessage} />
256→              );
257→            })}
258→          </>
259→        )}
260→      </div>
261→
262→      {isArchived && messages.length > 0 ? (
263→        <div className="border-t px-4 py-2 text-center text-xs text-muted-foreground">
264→          This session has ended
265→        </div>
266→      ) : (
267→        <form
268→          onSubmit={handleSubmit}
269→          className="relative flex gap-2 border-t px-2 py-2 md:px-4 md:py-3"
270→        >
271→          {showSlashMenu && (
272→            <SlashCommandMenu
273→              query={slashQuery}
274→              highlightedIndex={slashHighlight}
275→              onSelect={handleCommandSelect}
276→              onHighlight={setSlashHighlight}
277→            />
278→          )}
279→          <input
280→            ref={inputRef}
281→            type="text"
282→            value={input}
283→            onChange={handleInputChange}
284→            onKeyDown={handleKeyDown}
285→            placeholder={isActive ? "Send a follow-up..." : "Enter a prompt to spawn agent..."}
286→            className="flex-1 rounded-md border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring"
287→          />
288→          <Button type="submit" disabled={!connected || !input.trim()}>
289→            {isActive ? "Send" : "Spawn"}
290→          </Button>
291→        </form>
292→      )}
293→    </div>
294→  );
295→}
296→
297→/** Badge color per Claude NDJSON message type. */
298→const TYPE_COLORS: Record<string, string> = {
299→  system: "text-yellow-500",
300→  assistant: "text-blue-400",
301→  result: "text-green-500",
302→  control_request: "text-orange-400",
303→  keep_alive: "text-muted-foreground",
304→};
