  1→"use client";
  2→
  3→/**
  4→ * Tool approval card shown when Claude requests permission to run a tool.
  5→ *
  6→ * Displays the tool name with formatted input parameters, Allow / Deny buttons,
  7→ * and a resolved state with colored badge. Rendered in place of a regular
  8→ * {@link Message} when the message carries a `controlRequest` payload.
  9→ */
 10→
 11→import { Button } from "@/components/ui/button";
 12→import { Check, ShieldAlert, X } from "lucide-react";
 13→import type { ChatMessage } from "@/lib/types";
 14→
 15→/** Format "Mcp__server__tool_name" → { display: "tool_name", namespace: "server" } */
 16→function formatToolName(raw: string): { display: string; namespace?: string } {
 17→  // MCP namespaced tools: Mcp__<server>__<tool>
 18→  const mcpMatch = raw.match(/^Mcp__([^_]+(?:__[^_]+)*)__(.+)$/);
 19→  if (mcpMatch) {
 20→    return { display: mcpMatch[2], namespace: mcpMatch[1] };
 21→  }
 22→  return { display: raw };
 23→}
 24→
 25→/** Determine if a string value is "long" (multi-line or > 80 chars). */
 26→function isLongValue(value: string): boolean {
 27→  return value.includes("\n") || value.length > 80;
 28→}
 29→
 30→function InputField({ name, value }: { name: string; value: unknown }) {
 31→  if (value === null || value === undefined) return null;
 32→
 33→  // String values: short → inline code, long → scrollable code block
 34→  if (typeof value === "string") {
 35→    return (
 36→      <div className="space-y-1">
 37→        <div className="text-xs font-medium text-muted-foreground">{name}</div>
 38→        {isLongValue(value) ? (
 39→          <pre className="max-h-48 overflow-auto rounded bg-secondary p-2 text-xs whitespace-pre-wrap break-all">
 40→            {value}
 41→          </pre>
 42→        ) : (
 43→          <code className="rounded bg-secondary px-1.5 py-0.5 text-xs">{value}</code>
 44→        )}
 45→      </div>
 46→    );
 47→  }
 48→
 49→  // Boolean / number: inline code
 50→  if (typeof value === "boolean" || typeof value === "number") {
 51→    return (
 52→      <div className="space-y-1">
 53→        <div className="text-xs font-medium text-muted-foreground">{name}</div>
 54→        <code className="rounded bg-secondary px-1.5 py-0.5 text-xs">{String(value)}</code>
 55→      </div>
 56→    );
 57→  }
 58→
 59→  // Arrays and objects: JSON code block
 60→  return (
 61→    <div className="space-y-1">
 62→      <div className="text-xs font-medium text-muted-foreground">{name}</div>
 63→      <pre className="max-h-48 overflow-auto rounded bg-secondary p-2 text-xs">
 64→        {JSON.stringify(value, null, 2)}
 65→      </pre>
 66→    </div>
 67→  );
 68→}
 69→
 70→export function ControlRequest({
 71→  message,
 72→  onRespond,
 73→}: {
 74→  message: ChatMessage;
 75→  onRespond: (requestId: string, allow: boolean) => void;
 76→}) {
 77→  const cr = message.controlRequest;
 78→  if (!cr) return null;
 79→
 80→  const { display, namespace } = formatToolName(cr.tool_name);
 81→
 82→  return (
 83→    <div
 84→      className={`mx-auto w-full max-w-2xl rounded-lg border-2 border-dashed border-muted-foreground/30 p-3 md:p-4 ${
 85→        cr.resolved ? "opacity-60" : ""
 86→      }`}
 87→    >
 88→      {/* Header */}
 89→      <div className="mb-3 flex items-center gap-2">
 90→        <ShieldAlert className="h-4 w-4 shrink-0 text-yellow-500" />
 91→        <span className="text-sm font-semibold">{display}</span>
 92→        {namespace && (
 93→          <span className="text-xs text-muted-foreground">{namespace}</span>
 94→        )}
 95→      </div>
 96→
 97→      {/* Description */}
 98→      {cr.description && (
 99→        <p className="mb-3 text-xs text-muted-foreground">{cr.description}</p>
100→      )}
101→
102→      {/* Input parameters */}
103→      <div className="mb-3 space-y-2">
104→        {Object.entries(cr.input).map(([key, value]) => (
105→          <InputField key={key} name={key} value={value} />
106→        ))}
107→      </div>
108→
109→      {/* Actions / Resolved state */}
110→      {!cr.resolved ? (
111→        <div className="flex gap-2">
112→          <Button size="sm" onClick={() => onRespond(cr.id, true)}>
113→            <Check className="mr-1 h-3 w-3" />
114→            Allow
115→          </Button>
116→          <Button
117→            size="sm"
118→            variant="outline"
119→            onClick={() => onRespond(cr.id, false)}
120→          >
121→            <X className="mr-1 h-3 w-3" />
122→            Deny
123→          </Button>
124→        </div>
125→      ) : (
126→        <span
127→          className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium ${
128→            cr.allowed
129→              ? "bg-green-500/15 text-green-400"
130→              : "bg-red-500/15 text-red-400"
131→          }`}
132→        >
133→          {cr.allowed ? "Allowed" : "Denied"}
134→        </span>
135→      )}
136→    </div>
137→  );
138→}
