  1→"use client";
  2→
  3→/**
  4→ * Compact summary bar showing cost, duration, turn count, and token usage
  5→ * for an agent.
  6→ *
  7→ * Extracts stats from the raw Claude NDJSON message stream by scanning for
  8→ * `result` type messages. For multi-turn sessions:
  9→ * - **Cost**: last result's `total_cost_usd` (cumulative across the session)
 10→ * - **Duration**: sum of all `duration_ms` values (per-interaction wall clock)
 11→ * - **Turns**: sum of all `num_turns` values (per-interaction)
 12→ * - **Tokens**: sum of `input_tokens` + `output_tokens` from each result's
 13→ *   `usage` object (includes cache read/creation counts in the tooltip)
 14→ */
 15→
 16→import { useMemo } from "react";
 17→import { Clock, DollarSign, RotateCw, Zap } from "lucide-react";
 18→import type { ClaudeMessage, ClaudeResult } from "@/lib/types";
 19→
 20→interface ResultUsage {
 21→  input_tokens?: number;
 22→  output_tokens?: number;
 23→  cache_read_input_tokens?: number;
 24→  cache_creation_input_tokens?: number;
 25→}
 26→
 27→interface AgentStats {
 28→  totalCost: number;
 29→  totalDurationMs: number;
 30→  totalTurns: number;
 31→  inputTokens: number;
 32→  outputTokens: number;
 33→  cacheReadTokens: number;
 34→  cacheCreationTokens: number;
 35→}
 36→
 37→function computeStats(rawMessages: ClaudeMessage[]): AgentStats | null {
 38→  const results: (ClaudeResult & { usage?: ResultUsage })[] = [];
 39→  for (const msg of rawMessages) {
 40→    if (msg.type === "result") {
 41→      results.push(msg as ClaudeResult & { usage?: ResultUsage });
 42→    }
 43→  }
 44→  if (results.length === 0) return null;
 45→
 46→  const lastResult = results[results.length - 1];
 47→  const totalCost = lastResult.total_cost_usd ?? lastResult.cost_usd ?? 0;
 48→  const totalDurationMs = results.reduce((sum, r) => sum + (r.duration_ms ?? 0), 0);
 49→  const totalTurns = results.reduce((sum, r) => sum + (r.num_turns ?? 0), 0);
 50→
 51→  let inputTokens = 0;
 52→  let outputTokens = 0;
 53→  let cacheReadTokens = 0;
 54→  let cacheCreationTokens = 0;
 55→  for (const r of results) {
 56→    const u = r.usage;
 57→    if (!u) continue;
 58→    inputTokens += u.input_tokens ?? 0;
 59→    outputTokens += u.output_tokens ?? 0;
 60→    cacheReadTokens += u.cache_read_input_tokens ?? 0;
 61→    cacheCreationTokens += u.cache_creation_input_tokens ?? 0;
 62→  }
 63→
 64→  return { totalCost, totalDurationMs, totalTurns, inputTokens, outputTokens, cacheReadTokens, cacheCreationTokens };
 65→}
 66→
 67→function formatDuration(ms: number): string {
 68→  if (ms < 1000) return `${ms}ms`;
 69→  const seconds = ms / 1000;
 70→  if (seconds < 60) return `${seconds.toFixed(1)}s`;
 71→  const minutes = Math.floor(seconds / 60);
 72→  const remainingSeconds = Math.round(seconds % 60);
 73→  return `${minutes}m ${remainingSeconds}s`;
 74→}
 75→
 76→function formatCost(usd: number): string {
 77→  if (usd < 0.01) return `$${usd.toFixed(4)}`;
 78→  return `$${usd.toFixed(2)}`;
 79→}
 80→
 81→function formatTokens(n: number): string {
 82→  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
 83→  if (n >= 1_000) return `${(n / 1_000).toFixed(1)}k`;
 84→  return `${n}`;
 85→}
 86→
 87→export function AgentSummary({ rawMessages }: { rawMessages: ClaudeMessage[] }) {
 88→  const stats = useMemo(() => computeStats(rawMessages), [rawMessages]);
 89→
 90→  if (!stats) return null;
 91→
 92→  const totalTokens = stats.inputTokens + stats.outputTokens + stats.cacheReadTokens + stats.cacheCreationTokens;
 93→  const tokenTooltip = [
 94→    `Input: ${formatTokens(stats.inputTokens)}`,
 95→    `Output: ${formatTokens(stats.outputTokens)}`,
 96→    `Cache read: ${formatTokens(stats.cacheReadTokens)}`,
 97→    `Cache write: ${formatTokens(stats.cacheCreationTokens)}`,
 98→  ].join("\n");
 99→
100→  return (
101→    <div className="flex items-center gap-3 border-b px-4 py-1.5 text-[11px] text-muted-foreground">
102→      <span className="flex items-center gap-1" title="Total cost">
103→        <DollarSign className="size-3" />
104→        {formatCost(stats.totalCost)}
105→      </span>
106→      <span className="flex items-center gap-1" title="Total duration">
107→        <Clock className="size-3" />
108→        {formatDuration(stats.totalDurationMs)}
109→      </span>
110→      <span className="flex items-center gap-1" title="Total turns">
111→        <RotateCw className="size-3" />
112→        {stats.totalTurns} {stats.totalTurns === 1 ? "turn" : "turns"}
113→      </span>
114→      <span className="flex items-center gap-1" title={tokenTooltip}>
115→        <Zap className="size-3" />
116→        {formatTokens(totalTokens)} tokens
117→      </span>
118→    </div>
119→  );
120→}
