  1→/**
  2→ * Shared type definitions for the thos dashboard.
  3→ *
  4→ * Three categories:
  5→ * 1. **Claude NDJSON protocol** — messages the Claude CLI sends over its
  6→ *    `--sdk-url` WebSocket connection (CLI → WS server).
  7→ * 2. **Browser ↔ Server** — messages exchanged between the React client
  8→ *    and the standalone WS relay server.
  9→ * 3. **UI state** — view-model types consumed by React components.
 10→ *
 11→ * ## Key architecture notes
 12→ *
 13→ * - On browser connect, the server sends `agent_list` + `task_list` only.
 14→ * - Message histories are loaded lazily: the browser sends
 15→ *   `request_history` when selecting an agent, and the server responds
 16→ *   with `message_history` for that single agent.
 17→ * - Live messages for active agents are broadcast via `relay` in real time.
 18→ * - See `server/ws.ts` and `hooks/use-websocket.ts` for implementation.
 19→ */
 20→
 21→// ── Claude NDJSON protocol messages (CLI → server) ────────────────────────
 22→
 23→/**
 24→ * Sent once after the first user prompt is received. Contains session
 25→ * metadata like the model name, working directory, and available tools.
 26→ */
 27→export interface ClaudeSystemInit {
 28→  type: "system";
 29→  subtype: "init";
 30→  session_id: string;
 31→  tools: unknown[];
 32→  mcp_servers: unknown[];
 33→  model: string;
 34→  cwd: string;
 35→}
 36→
 37→/**
 38→ * An assistant turn. `message.content` is an array of content blocks
 39→ * (text, tool_use, tool_result) that may arrive incrementally — each
 40→ * NDJSON line is a complete snapshot of the message so far.
 41→ */
 42→export interface ClaudeAssistant {
 43→  type: "assistant";
 44→  message: {
 45→    id: string;
 46→    role: "assistant";
 47→    content: AssistantContentBlock[];
 48→    model: string;
 49→    stop_reason: string | null;
 50→  };
 51→  session_id: string;
 52→}
 53→
 54→/** A single content block inside an assistant message. */
 55→export type AssistantContentBlock =
 56→  | { type: "text"; text: string }
 57→  | { type: "tool_use"; id: string; name: string; input: Record<string, unknown> }
 58→  | { type: "tool_result"; tool_use_id: string; content: string };
 59→
 60→/**
 61→ * Terminal message for a session. Includes cost/duration metrics.
 62→ * `is_error` is true when `subtype` is `"error"`.
 63→ */
 64→export interface ClaudeResult {
 65→  type: "result";
 66→  subtype: "success" | "error";
 67→  result?: string;
 68→  error?: string;
 69→  session_id: string;
 70→  cost_usd: number;
 71→  total_cost_usd?: number;
 72→  duration_ms: number;
 73→  duration_api_ms: number;
 74→  is_error: boolean;
 75→  num_turns: number;
 76→}
 77→
 78→/**
 79→ * Claude is requesting permission to execute a tool. The dashboard must
 80→ * reply with a `control_response` (allow / deny) before the CLI proceeds.
 81→ *
 82→ * Wire format uses a nested `request` object with `request_id` at the
 83→ * top level for correlation (matches Companion protocol docs).
 84→ */
 85→export interface ClaudeControlRequest {
 86→  type: "control_request";
 87→  request_id: string;
 88→  request: {
 89→    subtype: "can_use_tool";
 90→    tool_name: string;
 91→    input: Record<string, unknown>;
 92→    tool_use_id?: string;
 93→    description?: string;
 94→  };
 95→  session_id?: string;
 96→}
 97→
 98→/**
 99→ * Hook lifecycle events emitted during CLI startup. `hook_response` is
100→ * the signal that the CLI is ready to receive the first user prompt.
101→ */
102→export interface ClaudeSystemHook {
103→  type: "system";
104→  subtype: "hook_started" | "hook_response";
105→  session_id?: string;
106→}
107→
108→/** Discriminated union of all known Claude NDJSON message shapes. */
109→export type ClaudeMessage =
110→  | ClaudeSystemInit
111→  | ClaudeAssistant
112→  | ClaudeResult
113→  | ClaudeControlRequest
114→  | ClaudeSystemHook
115→  | { type: string; subtype?: string; [key: string]: unknown };
116→
117→// ── Workspaces ───────────────────────────────────────────────────────────
118→
119→/** A workspace represents a project directory. */
120→export interface Workspace {
121→  id: string;
122→  name: string;
123→  cwd: string;
124→  createdAt: number;
125→}
126→
127→/** A directory entry returned by the server-side folder browser. */
128→export interface DirectoryEntry {
129→  name: string;
130→  path: string;
131→}
132→
133→// ── Browser ↔ Server messages ─────────────────────────────────────────────
134→
135→/** Browser asks the server to spawn a new Claude CLI process. */
136→export interface BrowserSpawn {
137→  type: "spawn";
138→  prompt: string;
139→  workspaceId?: string;
140→  /** Optional model override (e.g. "claude-opus-4-20250514", "qwen3-coder"). */
141→  model?: string;
142→}
143→
144→/** Browser sends a follow-up message to an already-running Claude session. */
145→export interface BrowserSendMessage {
146→  type: "send_message";
147→  agentId: string;
148→  content: string;
149→}
150→
151→/** Browser responds to a tool approval request (allow or deny). */
152→export interface BrowserControlResponse {
153→  type: "control_response";
154→  agentId: string;
155→  request_id: string;
156→  allow: boolean;
157→}
158→
159→/** Browser asks the server to kill a running agent's tmux session + CLI. */
160→export interface BrowserKillAgent {
161→  type: "kill_agent";
162→  agentId: string;
163→}
164→
165→/** Browser asks the server to permanently delete an agent. */
166→export interface BrowserDeleteAgent {
167→  type: "delete_agent";
168→  agentId: string;
169→}
170→
171→/** Browser asks the server to rename an agent. */
172→export interface BrowserRenameAgent {
173→  type: "rename_agent";
174→  agentId: string;
175→  label: string;
176→}
177→
178→/** Browser asks the server to clear an agent's message history. */
179→export interface BrowserClearHistory {
180→  type: "clear_history";
181→  agentId: string;
182→}
183→
184→/** Browser asks the server to pin or unpin an agent. */
185→export interface BrowserPinAgent {
186→  type: "pin_agent";
187→  agentId: string;
188→  pinned: boolean;
189→}
190→
191→/** Browser asks the server to icebox or un-icebox an agent. */
192→export interface BrowserIceboxAgent {
193→  type: "icebox_agent";
194→  agentId: string;
195→  iceboxed: boolean;
196→}
197→
198→/** Browser requests message history for a specific agent (lazy loading). */
199→export interface BrowserRequestHistory {
200→  type: "request_history";
201→  agentId: string;
202→}
203→
204→/** Browser asks the server to create a new task. */
205→export interface BrowserCreateTask {
206→  type: "create_task";
207→  title: string;
208→  description: string;
209→  priority: TaskPriority;
210→}
211→
212→/** Browser asks to update a task's fields. */
213→export interface BrowserUpdateTask {
214→  type: "update_task";
215→  taskId: string;
216→  updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>;
217→}
218→
219→/** Browser asks to delete a task. */
220→export interface BrowserDeleteTask {
221→  type: "delete_task";
222→  taskId: string;
223→}
224→
225→/** Browser asks to delegate a task to a new Claude agent. */
226→export interface BrowserDelegateTask {
227→  type: "delegate_task";
228→  taskId: string;
229→}
230→
231→/** Browser tells the server which workspace to scope to. */
232→export interface BrowserSetWorkspace {
233→  type: "set_workspace";
234→  workspaceId: string | null;
235→}
236→
237→/** Browser asks the server to create a new workspace. */
238→export interface BrowserCreateWorkspace {
239→  type: "create_workspace";
240→  name: string;
241→  cwd: string;
242→}
243→
244→/** Browser asks to rename a workspace. */
245→export interface BrowserRenameWorkspace {
246→  type: "rename_workspace";
247→  workspaceId: string;
248→  name: string;
249→}
250→
251→/** Browser asks to delete a workspace. */
252→export interface BrowserDeleteWorkspace {
253→  type: "delete_workspace";
254→  workspaceId: string;
255→}
256→
257→/** Browser asks to browse a directory on the server. */
258→export interface BrowserBrowseDirectory {
259→  type: "browse_directory";
260→  path: string;
261→}
262→
263→/** Union of all messages the browser can send to the WS server. */
264→export type BrowserMessage =
265→  | BrowserSpawn
266→  | BrowserSendMessage
267→  | BrowserControlResponse
268→  | BrowserKillAgent
269→  | BrowserDeleteAgent
270→  | BrowserRenameAgent
271→  | BrowserClearHistory
272→  | BrowserPinAgent
273→  | BrowserIceboxAgent
274→  | BrowserRequestHistory
275→  | BrowserCreateTask
276→  | BrowserUpdateTask
277→  | BrowserDeleteTask
278→  | BrowserDelegateTask
279→  | BrowserSetWorkspace
280→  | BrowserCreateWorkspace
281→  | BrowserRenameWorkspace
282→  | BrowserDeleteWorkspace
283→  | BrowserBrowseDirectory;
284→
285→/** Server relays a raw Claude NDJSON message to the browser. */
286→export interface ServerRelay {
287→  type: "relay";
288→  agentId: string;
289→  message: ClaudeMessage;
290→}
291→
292→/** Server notifies the browser of an agent status change. */
293→export interface ServerStatus {
294→  type: "status";
295→  agentId: string;
296→  status: AgentStatus;
297→}
298→
299→/** Server reports an error (e.g. no active session, process crash). */
300→export interface ServerError {
301→  type: "error";
302→  agentId: string;
303→  error: string;
304→}
305→
306→/** Summary of an agent for the sidebar. */
307→export interface AgentInfo {
308→  agentId: string;
309→  status: AgentStatus;
310→  tmuxSession: string | null;
311→  label: string;
312→  createdAt: number;
313→  workspaceId: string | null;
314→  /** Model name reported by system/init, or the model requested at spawn time. */
315→  model?: string | null;
316→  /** Whether this agent is pinned to the top of the sidebar. */
317→  pinned?: boolean;
318→  /** Whether this agent is in the icebox (parked for later). */
319→  iceboxed?: boolean;
320→}
321→
322→/** Server sends the full list of agents after every state change. */
323→export interface ServerAgentList {
324→  type: "agent_list";
325→  agents: AgentInfo[];
326→}
327→
328→/** Server confirms a new agent was spawned and assigns its ID. */
329→export interface ServerSpawned {
330→  type: "spawned";
331→  agentId: string;
332→}
333→
334→/** Server sends full message history for an agent (in response to `request_history`). */
335→export interface ServerMessageHistory {
336→  type: "message_history";
337→  agentId: string;
338→  messages: ServerMessage[];
339→}
340→
341→/** CLI WebSocket disconnected (process may have crashed or exited). */
342→export interface ServerCliDisconnected {
343→  type: "cli_disconnected";
344→  agentId: string;
345→}
346→
347→/** CLI WebSocket reconnected (e.g. after relaunch with --resume). */
348→export interface ServerCliConnected {
349→  type: "cli_connected";
350→  agentId: string;
351→}
352→
353→/** Server confirms message history was cleared for an agent. */
354→export interface ServerHistoryCleared {
355→  type: "history_cleared";
356→  agentId: string;
357→}
358→
359→/** Server sends the full workspace list to the browser. */
360→export interface ServerWorkspaceList {
361→  type: "workspace_list";
362→  workspaces: Workspace[];
363→}
364→
365→/** Server responds with a directory listing for the folder browser. */
366→export interface ServerDirectoryListing {
367→  type: "directory_listing";
368→  path: string;
369→  entries: DirectoryEntry[];
370→}
371→
372→/** Server sends the full task list to the browser. */
373→export interface ServerTaskList {
374→  type: "task_list";
375→  tasks: Task[];
376→}
377→
378→/** Server confirms a task was updated. */
379→export interface ServerTaskUpdated {
380→  type: "task_updated";
381→  task: Task;
382→}
383→
384→/** Server confirms a task was deleted. */
385→export interface ServerTaskDeleted {
386→  type: "task_deleted";
387→  taskId: string;
388→}
389→
390→/** Union of all messages the WS server can send to the browser. */
391→export type ServerMessage =
392→  | ServerRelay
393→  | ServerStatus
394→  | ServerError
395→  | ServerAgentList
396→  | ServerSpawned
397→  | ServerMessageHistory
398→  | ServerCliDisconnected
399→  | ServerCliConnected
400→  | ServerHistoryCleared
401→  | ServerWorkspaceList
402→  | ServerDirectoryListing
403→  | ServerTaskList
404→  | ServerTaskUpdated
405→  | ServerTaskDeleted;
406→
407→// ── UI state ──────────────────────────────────────────────────────────────
408→
409→/**
410→ * Lifecycle states of the Claude agent process:
411→ * - `idle`      — no process running, ready to spawn
412→ * - `spawning`  — process launched, waiting for CLI to connect via WS
413→ * - `connected` — CLI connected and `system/init` received
414→ * - `thinking`  — waiting for assistant response
415→ * - `done`      — `result` message received, process finished
416→ * - `error`     — process crashed or unexpected failure
417→ */
418→export type AgentStatus = "idle" | "spawning" | "connected" | "thinking" | "done" | "disconnected" | "error";
419→
420→export type ChatMessageRole = "user" | "assistant" | "system";
421→
422→/**
423→ * A single entry in the chat message list. System messages include
424→ * session init info and result summaries. Messages with a `controlRequest`
425→ * are rendered as tool-approval cards instead of plain bubbles.
426→ */
427→/** A single option in an AskUserQuestion question. */
428→export interface UserQuestionOption {
429→  label: string;
430→  description?: string;
431→}
432→
433→/** A single question from AskUserQuestion. */
434→export interface UserQuestion {
435→  question: string;
436→  header?: string;
437→  options: UserQuestionOption[];
438→  multiSelect: boolean;
439→}
440→
441→/** Info about a single tool_use block in an assistant message. */
442→export interface ToolCallInfo {
443→  name: string;
444→  toolUseId?: string;
445→  /** Truncated one-line preview of the tool result, if available. */
446→  resultPreview?: string;
447→  /** Raw tool input data, preserved for file-modifying tools (Edit, Write, MultiEdit). */
448→  input?: Record<string, unknown>;
449→}
450→
451→export interface ChatMessage {
452→  id: string;
453→  role: ChatMessageRole;
454→  content: string;
455→  timestamp: number;
456→  /** Present when this message represents a tool approval request. */
457→  controlRequest?: {
458→    id: string;
459→    tool_name: string;
460→    input: Record<string, unknown>;
461→    /** Tool description from the protocol, if available. */
462→    description?: string;
463→    /** Set to true after the user allows or denies. */
464→    resolved?: boolean;
465→    /** Whether the user allowed (true) or denied (false). */
466→    allowed?: boolean;
467→  };
468→  /** Present when this message is an AskUserQuestion control request. */
469→  userQuestion?: {
470→    requestId: string;
471→    questions: UserQuestion[];
472→    resolved?: boolean;
473→  };
474→  /** Tool calls found in this assistant message. */
475→  toolCalls?: ToolCallInfo[];
476→  /** True when this message has only tool_use/tool_result blocks and no text. */
477→  isToolOnly?: boolean;
478→}
479→
480→// ── Task system ──────────────────────────────────────────────────────────
481→
482→export type TaskStatus = "icebox" | "todo" | "in-progress" | "done";
483→export type TaskPriority = "low" | "medium" | "high" | "urgent";
484→
485→/** A user-created task, optionally linked to a Claude agent. */
486→export interface Task {
487→  id: string;
488→  title: string;
489→  description: string;
490→  status: TaskStatus;
491→  priority: TaskPriority;
492→  /** If delegated, the agentId of the spawned Claude agent. */
493→  agentId: string | null;
494→  /** Workspace this task belongs to. */
495→  workspaceId: string | null;
496→  createdAt: number;
497→  updatedAt: number;
498→}
