  1→"use client";
  2→
  3→/**
  4→ * Collapsible group for consecutive tool-only assistant messages.
  5→ *
  6→ * When Claude runs multiple tools in a row without any prose text,
  7→ * {@link condenseMessages} in `lib/condense-messages.ts` groups them
  8→ * into a {@link CondensedGroup}. This component renders that group.
  9→ *
 10→ * ## Two-level expand
 11→ *
 12→ * 1. **Group level** — The top chevron toggles between the compact
 13→ *    per-tool-call summary (collapsed) and the full message bubbles
 14→ *    (expanded). This is the original behavior.
 15→ *
 16→ * 2. **Diff level** — In the collapsed view, file-modifying tool calls
 17→ *    (Edit, Write, MultiEdit) show the file basename and are clickable.
 18→ *    Clicking one toggles an inline {@link DiffViewer} for just that
 19→ *    tool call, without expanding the whole group. Multiple diffs can
 20→ *    be open at once (tracked in the `expandedDiffs` Set).
 21→ *
 22→ * Non-diff tool calls (Read, Bash, Grep, etc.) continue to show the
 23→ * truncated `resultPreview` text as before.
 24→ */
 25→
 26→import { useState } from "react";
 27→import { ChevronRight } from "lucide-react";
 28→import type { CondensedGroup } from "@/lib/condense-messages";
 29→import type { ToolCallInfo } from "@/lib/types";
 30→import { Message } from "./message";
 31→import { DiffViewer } from "./diff-viewer";
 32→import { cn } from "@/lib/utils";
 33→
 34→/** Colored dot per common tool name (used in the compact summary line). */
 35→const TOOL_COLORS: Record<string, string> = {
 36→  Read: "bg-blue-400",
 37→  Write: "bg-green-400",
 38→  Edit: "bg-yellow-400",
 39→  Bash: "bg-orange-400",
 40→  Glob: "bg-purple-400",
 41→  Grep: "bg-cyan-400",
 42→  WebFetch: "bg-pink-400",
 43→  Task: "bg-indigo-400",
 44→  TodoWrite: "bg-teal-400",
 45→};
 46→
 47→/** Tool names that produce renderable diffs (same set as in diff-viewer). */
 48→const DIFF_TOOLS = new Set(["Edit", "Write", "MultiEdit"]);
 49→
 50→export function CondensedToolGroup({ group, onSendMessage }: { group: CondensedGroup; onSendMessage?: (content: string) => void }) {
 51→  /** Whether the full message list is shown (group-level expand). */
 52→  const [expanded, setExpanded] = useState(false);
 53→  /** Which individual diffs are open in the collapsed view (by key). */
 54→  const [expandedDiffs, setExpandedDiffs] = useState<Set<string>>(new Set());
 55→
 56→  // Collect all tool calls with previews for the collapsed view
 57→  const allToolCalls: ToolCallInfo[] = [];
 58→  for (const msg of group.messages) {
 59→    for (const tc of msg.toolCalls ?? []) {
 60→      allToolCalls.push(tc);
 61→    }
 62→  }
 63→
 64→  function toggleDiff(key: string) {
 65→    setExpandedDiffs((prev) => {
 66→      const next = new Set(prev);
 67→      if (next.has(key)) next.delete(key);
 68→      else next.add(key);
 69→      return next;
 70→    });
 71→  }
 72→
 73→  return (
 74→    <div className="py-1">
 75→      <button
 76→        onClick={() => setExpanded((v) => !v)}
 77→        aria-expanded={expanded}
 78→        className="flex w-full items-center gap-2 rounded-md px-3 py-1.5 text-xs text-muted-foreground hover:bg-muted/50 transition-colors"
 79→      >
 80→        <ChevronRight
 81→          className={cn(
 82→            "size-3 shrink-0 transition-transform",
 83→            expanded && "rotate-90"
 84→          )}
 85→        />
 86→        <span className="font-mono">{group.summary}</span>
 87→      </button>
 88→
 89→      {!expanded && allToolCalls.length > 0 && (
 90→        <div className="ml-5 mt-0.5 space-y-0.5 pl-3">
 91→          {allToolCalls.map((tc, i) => {
 92→            const key = `${tc.toolUseId ?? "tc"}-${i}`;
 93→            const hasDiff = tc.input && DIFF_TOOLS.has(tc.name);
 94→            const diffOpen = expandedDiffs.has(key);
 95→
 96→            return (
 97→              <div key={key}>
 98→                <div
 99→                  className={cn(
100→                    "flex items-center gap-1.5 text-[10px] text-muted-foreground/70 truncate",
101→                    hasDiff && "cursor-pointer hover:text-muted-foreground"
102→                  )}
103→                  onClick={hasDiff ? () => toggleDiff(key) : undefined}
104→                >
105→                  <span className={cn("inline-block size-1.5 shrink-0 rounded-full", TOOL_COLORS[tc.name] ?? "bg-muted-foreground/50")} />
106→                  <span className="font-mono shrink-0">{tc.name}</span>
107→                  {hasDiff && tc.input?.file_path ? (
108→                    <span className="truncate font-mono opacity-80">
109→                      {String(tc.input.file_path).split("/").pop()}
110→                    </span>
111→                  ) : tc.resultPreview ? (
112→                    <span className="truncate opacity-60">{tc.resultPreview}</span>
113→                  ) : null}
114→                </div>
115→                {hasDiff && diffOpen && (
116→                  <div className="mt-1 mb-1">
117→                    <DiffViewer toolCall={tc} onComment={onSendMessage} />
118→                  </div>
119→                )}
120→              </div>
121→            );
122→          })}
123→        </div>
124→      )}
125→
126→      {expanded && (
127→        <div className="ml-5 mt-1 space-y-1 border-l border-muted pl-3">
128→          {group.messages.map((msg) => (
129→            <Message key={msg.id} message={msg} onSendMessage={onSendMessage} />
130→          ))}
131→        </div>
132→      )}
133→    </div>
134→  );
135→}
