190→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse" />
191→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:150ms]" />
192→              <div className="size-2 rounded-full bg-muted-foreground/40 animate-pulse [animation-delay:300ms]" />
193→            </div>
194→            <span className="text-xs text-muted-foreground">
195→              {connected ? "Loading messages..." : "Connecting..."}
196→            </span>
197→          </div>
198→        ) : showRaw ? (
199→          rawMessages.length === 0 ? (
200→            <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
201→              No raw messages yet
202→            </div>
203→          ) : (
204→            <div className="space-y-1">
205→              {rawMessages.map((msg, i) => (
206→                <RawMessage key={i} message={msg} index={i} />
207→              ))}
208→            </div>
209→          )
210→        ) : (
211→          <>
212→            {messages.length === 0 && (
213→              <div className="flex h-full flex-col items-center justify-center gap-4 text-muted-foreground">
214→                <Terminal className="size-10 opacity-30" />
215→                <div className="text-center">
216→                  <p className="text-sm font-medium text-foreground/80">No agent selected</p>
217→                  <p className="mt-1 text-xs">Type a prompt below to spawn a Claude agent</p>
218→                </div>
219→                <div className="mt-2 grid grid-cols-2 gap-3 text-[11px]">
220→                  <div className="flex items-start gap-2 rounded-lg border p-3">
221→                    <MessageSquare className="mt-0.5 size-3.5 shrink-0 text-primary" />
222→                    <div>
223→                      <p className="font-medium text-foreground/80">Chat</p>
224→                      <p className="mt-0.5">Send prompts and review tool calls in real time</p>
225→                    </div>
226→                  </div>
227→                  <div className="flex items-start gap-2 rounded-lg border p-3">
228→                    <ListTodo className="mt-0.5 size-3.5 shrink-0 text-primary" />
229→                    <div>
230→                      <p className="font-medium text-foreground/80">Tasks</p>
231→                      <p className="mt-0.5">Track work with a kanban board and delegate to agents</p>
232→                    </div>
233→                  </div>
234→                </div>
235→              </div>
236→            )}
237→            {displayItems.map((item) => {
238→              if (item.kind === "condensed") {
239→                return <CondensedToolGroup key={item.id} group={item} onSendMessage={onSendMessage} />;
240→              }
241→              const msg = item.message;
242→              return msg.userQuestion ? (
243→                <UserQuestion
244→                  key={msg.id}
245→                  message={msg}
246→                  onRespond={onRespondToUserQuestion}
247→                />
248→              ) : msg.controlRequest ? (
249→                <ControlRequest
250→                  key={msg.id}
251→                  message={msg}
252→                  onRespond={onRespondToControl}
253→                />
254→              ) : (
255→                <Message key={msg.id} message={msg} onSendMessage={onSendMessage} />
256→              );
257→            })}
258→          </>
259→        )}
260→      </div>
261→
262→      {isArchived && messages.length > 0 ? (
263→        <div className="border-t px-4 py-2 text-center text-xs text-muted-foreground">
264→          This session has ended
265→        </div>
266→      ) : (
267→        <form
268→          onSubmit={handleSubmit}
269→          className="relative flex gap-2 border-t px-2 py-2 md:px-4 md:py-3"
270→        >
271→          {showSlashMenu && (
272→            <SlashCommandMenu
273→              query={slashQuery}
274→              highlightedIndex={slashHighlight}
275→              onSelect={handleCommandSelect}
276→              onHighlight={setSlashHighlight}
277→            />
278→          )}
279→          <input
280→            ref={inputRef}
281→            type="text"
282→            value={input}
283→            onChange={handleInputChange}
284→            onKeyDown={handleKeyDown}
285→            placeholder={isActive ? "Send a follow-up..." : "Enter a prompt to spawn agent..."}
286→            className="flex-1 rounded-md border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring"
287→          />
288→          <Button type="submit" disabled={!connected || !input.trim()}>
289→            {isActive ? "Send" : "Spawn"}
290→          </Button>
291→        </form>
292→      )}
293→    </div>
294→  );
295→}
296→
297→/** Badge color per Claude NDJSON message type. */
298→const TYPE_COLORS: Record<string, string> = {
299→  system: "text-yellow-500",
300→  assistant: "text-blue-400",
301→  result: "text-green-500",
302→  control_request: "text-orange-400",
303→  keep_alive: "text-muted-foreground",
304→};
305→
306→function RawMessage({ message, index }: { message: ClaudeMessage; index: number }) {
307→  const [expanded, setExpanded] = useState(false);
308→  const subtype = (message as { subtype?: string }).subtype;
309→  const typeLabel = subtype ? `${message.type}/${subtype}` : message.type;
310→  const colorClass = TYPE_COLORS[message.type] ?? "text-muted-foreground";
311→
312→  return (
313→    <div className="font-mono text-[11px] leading-relaxed">
314→      <button
315→        onClick={() => setExpanded((v) => !v)}
316→        className="flex w-full items-center gap-2 rounded px-2 py-1 text-left hover:bg-muted/50 transition-colors"
317→      >
318→        <span className="text-muted-foreground w-6 shrink-0 text-right">{index}</span>
319→        <span className={colorClass}>{typeLabel}</span>
320→        <span className="text-muted-foreground">{expanded ? "▼" : "▶"}</span>
321→      </button>
322→      {expanded && (
323→        <pre className="ml-10 overflow-x-auto rounded bg-muted/30 p-2 text-[10px] text-muted-foreground whitespace-pre-wrap break-all">
324→          {JSON.stringify(message, null, 2)}
325→        </pre>
326→      )}
327→    </div>
328→  );
329→}
