 43→// ── Parser ───────────────────────────────────────────────────────────────
 44→
 45→export function parseContextUsage(content: string): ContextUsageData | null {
 46→  const lines = content.split("\n");
 47→  const data: ContextUsageData = {
 48→    model: "",
 49→    usedTokens: "",
 50→    totalTokens: "",
 51→    percentage: 0,
 52→    categories: [],
 53→    memoryFiles: [],
 54→    skills: [],
 55→  };
 56→
 57→  let section: "main" | "categories" | "memory" | "skills" = "main";
 58→
 59→  for (const line of lines) {
 60→    const trimmed = line.trim();
 61→
 62→    // Model line: **Model:** claude-opus-4-6
 63→    const modelMatch = trimmed.match(/\*\*Model:\*\*\s*(.+)/);
 64→    if (modelMatch) {
 65→      data.model = modelMatch[1].trim();
 66→      continue;
 67→    }
 68→
 69→    // Tokens line: **Tokens:** 35.3k / 200k (18%)
 70→    const tokensMatch = trimmed.match(/\*\*Tokens:\*\*\s*([\d.]+k?)\s*\/\s*([\d.]+k?)\s*(?:tokens\s*)?\((\d+)%\)/);
 71→    if (tokensMatch) {
 72→      data.usedTokens = tokensMatch[1];
 73→      data.totalTokens = tokensMatch[2];
 74→      data.percentage = parseInt(tokensMatch[3], 10);
 75→      continue;
 76→    }
 77→
 78→    // Section headers
 79→    if (trimmed.startsWith("### Estimated usage")) {
 80→      section = "categories";
 81→      continue;
 82→    }
 83→    if (trimmed.startsWith("### Memory Files")) {
 84→      section = "memory";
 85→      continue;
 86→    }
 87→    if (trimmed.startsWith("### Skills")) {
 88→      section = "skills";
 89→      continue;
 90→    }
 91→
 92→    // Skip table headers and separators
 93→    if (trimmed.startsWith("| Category") || trimmed.startsWith("| Type") || trimmed.startsWith("| Skill") || trimmed.startsWith("|---")) {
 94→      continue;
 95→    }
 96→
 97→    // Parse table rows
 98→    if (trimmed.startsWith("|") && trimmed.endsWith("|")) {
 99→      const cols = trimmed.split("|").filter(Boolean).map((c) => c.trim());
100→      if (cols.length < 2) continue;
101→
102→      if (section === "categories" && cols.length >= 3) {
103→        const pctMatch = cols[2].match(/([\d.]+)%/);
104→        data.categories.push({
105→          name: cols[0],
106→          tokens: cols[1],
107→          pct: pctMatch ? parseFloat(pctMatch[1]) : 0,
108→        });
109→      } else if (section === "memory" && cols.length >= 3) {
110→        data.memoryFiles.push({
111→          type: cols[0],
112→          path: cols[1],
113→          tokens: cols[2],
114→        });
115→      } else if (section === "skills" && cols.length >= 3) {
116→        data.skills.push({
117→          skill: cols[0],
118→          source: cols[1],
119→          tokens: cols[2],
120→        });
121→      }
122→    }
123→  }
124→
125→  if (!data.model && !data.usedTokens) return null;
126→  return data;
127→}
