"use client";

import { useState } from "react";
import { ChevronDown, ChevronRight, Cpu, FileText, Zap } from "lucide-react";
import { cn } from "@/lib/utils";

// ── Types ────────────────────────────────────────────────────────────────

interface ContextCategory {
  name: string;
  tokens: string;
  pct: number;
}

interface MemoryFile {
  type: string;
  path: string;
  tokens: string;
}

interface SkillEntry {
  skill: string;
  source: string;
  tokens: string;
}

interface ContextUsageData {
  model: string;
  usedTokens: string;
  totalTokens: string;
  percentage: number;
  categories: ContextCategory[];
  memoryFiles: MemoryFile[];
  skills: SkillEntry[];
}

// ── Detection ────────────────────────────────────────────────────────────

export function isContextUsageMessage(content: string): boolean {
  return content.trimStart().startsWith("## Context Usage");
}

// ── Parser ───────────────────────────────────────────────────────────────

export function parseContextUsage(content: string): ContextUsageData | null {
  const lines = content.split("\n");
  const data: ContextUsageData = {
    model: "",
    usedTokens: "",
    totalTokens: "",
    percentage: 0,
    categories: [],
    memoryFiles: [],
    skills: [],
  };

  let section: "main" | "categories" | "memory" | "skills" = "main";

  for (const line of lines) {
    const trimmed = line.trim();

    // Model line: **Model:** claude-opus-4-6
    const modelMatch = trimmed.match(/\*\*Model:\*\*\s*(.+)/);
    if (modelMatch) {
      data.model = modelMatch[1].trim();
      continue;
    }

    // Tokens line: **Tokens:** 35.3k / 200k (18%)
    const tokensMatch = trimmed.match(/\*\*Tokens:\*\*\s*([\d.]+k?)\s*\/\s*([\d.]+k?)\s*(?:tokens\s*)?\((\d+)%\)/);
    if (tokensMatch) {
      data.usedTokens = tokensMatch[1];
      data.totalTokens = tokensMatch[2];
      data.percentage = parseInt(tokensMatch[3], 10);
      continue;
    }

    // Section headers
    if (trimmed.startsWith("### Estimated usage")) {
      section = "categories";
      continue;
    }
    if (trimmed.startsWith("### Memory Files")) {
      section = "memory";
      continue;
    }
    if (trimmed.startsWith("### Skills")) {
      section = "skills";
      continue;
    }

    // Skip table headers and separators
    if (trimmed.startsWith("| Category") || trimmed.startsWith("| Type") || trimmed.startsWith("| Skill") || trimmed.startsWith("|---")) {
      continue;
    }

    // Parse table rows
    if (trimmed.startsWith("|") && trimmed.endsWith("|")) {
      const cols = trimmed.split("|").filter(Boolean).map((c) => c.trim());
      if (cols.length < 2) continue;

      if (section === "categories" && cols.length >= 3) {
        const pctMatch = cols[2].match(/([\d.]+)%/);
        data.categories.push({
          name: cols[0],
          tokens: cols[1],
          pct: pctMatch ? parseFloat(pctMatch[1]) : 0,
        });
      } else if (section === "memory" && cols.length >= 3) {
        data.memoryFiles.push({
          type: cols[0],
          path: cols[1],
          tokens: cols[2],
        });
      } else if (section === "skills" && cols.length >= 3) {
        data.skills.push({
          skill: cols[0],
          source: cols[1],
          tokens: cols[2],
        });
      }
    }
  }

  if (!data.model && !data.usedTokens) return null;
  return data;
}

// ── Category colors ──────────────────────────────────────────────────────

const CATEGORY_COLORS: Record<string, string> = {
  "System prompt": "bg-yellow-500",
  "System tools": "bg-blue-400",
  "Memory files": "bg-purple-400",
  Skills: "bg-pink-400",
  Messages: "bg-green-400",
  "Free space": "bg-muted-foreground/20",
  "Autocompact buffer": "bg-orange-400",
};

function getCategoryColor(name: string): string {
  return CATEGORY_COLORS[name] ?? "bg-muted-foreground/40";
}

// ── Collapsible section ──────────────────────────────────────────────────

function CollapsibleSection({
  title,
  icon: Icon,
  count,
  children,
}: {
  title: string;
  icon: typeof FileText;
  count: number;
  children: React.ReactNode;
}) {
  const [open, setOpen] = useState(false);

  if (count === 0) return null;

  return (
    <div className="mt-3">
      <button
        onClick={() => setOpen((v) => !v)}
        className="flex w-full items-center gap-1.5 text-xs text-muted-foreground hover:text-foreground transition-colors"
      >
        {open ? <ChevronDown className="size-3" /> : <ChevronRight className="size-3" />}
        <Icon className="size-3" />
        <span>{title}</span>
        <span className="ml-auto tabular-nums">{count}</span>
      </button>
      {open && <div className="mt-1.5 space-y-1 pl-5">{children}</div>}
    </div>
  );
}

// ── Overall progress bar color ───────────────────────────────────────────

function getProgressColor(pct: number): string {
  if (pct < 50) return "bg-green-500";
  if (pct < 80) return "bg-yellow-500";
  return "bg-red-500";
}

// ── Main component ───────────────────────────────────────────────────────

export function ContextUsageCard({ content }: { content: string }) {
  const data = parseContextUsage(content);

  if (!data) {
    // Fallback: can't parse, just return null and let Message render normally
    return null;
  }

  const nonFreeCategories = data.categories.filter((c) => c.name !== "Free space");

  return (
    <div className="max-w-[90%] md:max-w-[80%] rounded-lg border bg-card px-4 py-3 space-y-3">
      {/* Header */}
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          <Cpu className="size-4 text-muted-foreground" />
          <span className="text-sm font-medium">Context Usage</span>
        </div>
        {data.model && (
          <span className="rounded-md bg-secondary px-2 py-0.5 text-[11px] font-mono text-muted-foreground">
            {data.model}
          </span>
        )}
      </div>

      {/* Token summary + overall bar */}
      <div className="space-y-1.5">
        <div className="flex items-baseline justify-between">
          <span className="text-2xl font-semibold tabular-nums">{data.usedTokens}</span>
          <span className="text-xs text-muted-foreground">
            / {data.totalTokens} tokens ({data.percentage}%)
          </span>
        </div>
        <div className="h-2 w-full rounded-full bg-secondary overflow-hidden">
          <div
            className={cn("h-full rounded-full transition-all", getProgressColor(data.percentage))}
            style={{ width: `${data.percentage}%` }}
          />
        </div>
      </div>

      {/* Stacked bar preview */}
      {data.categories.length > 0 && (
        <div className="flex h-3 w-full overflow-hidden rounded-full bg-secondary">
          {data.categories.map((cat) => (
            <div
              key={cat.name}
              className={cn("h-full first:rounded-l-full last:rounded-r-full", getCategoryColor(cat.name))}
              style={{ width: `${cat.pct}%` }}
              title={`${cat.name}: ${cat.tokens} (${cat.pct}%)`}
            />
          ))}
        </div>
      )}

      {/* Category breakdown */}
      {nonFreeCategories.length > 0 && (
        <div className="space-y-1.5">
          <span className="text-[11px] font-medium uppercase tracking-wider text-muted-foreground">
            Breakdown
          </span>
          {nonFreeCategories.map((cat) => (
            <div key={cat.name} className="flex items-center gap-2 text-xs">
              <div className={cn("size-2 rounded-full shrink-0", getCategoryColor(cat.name))} />
              <span className="flex-1 text-muted-foreground">{cat.name}</span>
              <span className="tabular-nums text-foreground/80">{cat.tokens}</span>
              <span className="w-12 text-right tabular-nums text-muted-foreground/60">
                {cat.pct}%
              </span>
            </div>
          ))}
        </div>
      )}

      {/* Memory files */}
      <CollapsibleSection title="Memory Files" icon={FileText} count={data.memoryFiles.length}>
        {data.memoryFiles.map((mf, i) => (
          <div key={i} className="flex items-center justify-between text-[11px]">
            <div className="flex items-center gap-1.5 min-w-0">
              <span className="rounded bg-purple-500/20 px-1 py-px text-purple-400 text-[10px]">
                {mf.type}
              </span>
              <span className="truncate text-muted-foreground font-mono">{mf.path}</span>
            </div>
            <span className="shrink-0 ml-2 tabular-nums text-muted-foreground">{mf.tokens}</span>
          </div>
        ))}
      </CollapsibleSection>

      {/* Skills */}
      <CollapsibleSection title="Skills" icon={Zap} count={data.skills.length}>
        {data.skills.map((sk, i) => (
          <div key={i} className="flex items-center justify-between text-[11px]">
            <div className="flex items-center gap-1.5 min-w-0">
              <span className="rounded bg-pink-500/20 px-1 py-px text-pink-400 text-[10px]">
                {sk.skill}
              </span>
              {sk.source !== "undefined" && (
                <span className="truncate text-muted-foreground">{sk.source}</span>
              )}
            </div>
            <span className="shrink-0 ml-2 tabular-nums text-muted-foreground">{sk.tokens}</span>
          </div>
        ))}
      </CollapsibleSection>
    </div>
  );
}

